fn draw_checkbox(c:&mut WidgetCanvas<'_>,s:&WidgetDrawSpec<'_>)->bool{let b=Rect{x:s.bounds.x+6,y:s.bounds.y+s.bounds.height.saturating_sub(16)/2,width:16,height:16};let active=s.checked||s.state==ControlState::Selected||s.state==ControlState::Pressed;let fill=if s.state==ControlState::Disabled{c.tokens.panel_raised}else if active{c.tokens.accent}else{c.tokens.panel};c.paint_round(b,3,fill,if active{0}else{c.tokens.control_edge},if active{0}else{1});if active{let Some(p)=c.pixel_rect(inset(b,2,2,2,2))else{return false};let sx=p.x+p.width/4;let mx=p.x+p.width*2/5;let ex=p.x+p.width*3/4;let my=p.y+p.height*3/5;let sy=p.y+p.height/2;let ey=p.y+p.height/4;let ink=if c.theme==Theme::Light{0xffffffff}else{c.tokens.window};line(c,sx as i64,sy as i64,mx as i64,my as i64,3,ink);line(c,mx as i64,my as i64,ex as i64,ey as i64,3,ink)}c.text(text(s.label),Rect{x:b.x+24,y:s.bounds.y,width:s.bounds.width.saturating_sub(36),height:s.bounds.height},c.state_fg(s.state),FontFamily::System,FontWeight::Regular,13)}
fn draw_segmented(c:&mut WidgetCanvas<'_>,s:&WidgetDrawSpec<'_>)->bool{let n=(if s.segment_count<2{3}else{s.segment_count as u32}).min(8);c.paint_round(s.bounds,6,c.tokens.panel_raised,c.tokens.separator,1);let sw=s.bounds.width/n;let selected=(s.segment_index as u32).min(n-1);c.paint_round(Rect{x:s.bounds.x+sw*selected+1,y:s.bounds.y+1,width:if sw>2{sw-2}else{sw},height:s.bounds.height.saturating_sub(2).max(1)},5,c.tokens.panel,0,0);for i in 1..n{c.paint_rect(Rect{x:s.bounds.x+sw*i,y:s.bounds.y+6,width:1,height:s.bounds.height.saturating_sub(12).max(1)},c.tokens.separator)}for(i,t)in s.segment_labels.iter().take(n as usize).enumerate(){let mut left=s.bounds.x+sw*i as u32+4;let right=s.bounds.x+sw*(i as u32+1);let label_width=(t.len()as u32).saturating_mul(7);let available=right.saturating_sub(left).saturating_sub(4);if label_width<available{left+=(available-label_width)/2}let bounds=Rect{x:left,y:s.bounds.y+1,width:right.saturating_sub(left).saturating_sub(2),height:s.bounds.height.saturating_sub(2).max(1)};if !c.text(t,bounds,c.state_fg(s.state),FontFamily::System,if i as u32==selected{FontWeight::Semibold}else{FontWeight::Regular},12){return false}}if s.segment_labels.is_empty(){c.text(text(s.label),inset(s.bounds,8,0,8,0),c.state_fg(s.state),FontFamily::System,FontWeight::Regular,13)}else{true}}
